package net.civeira.phylax.feature.observe.observedalert.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.event.ObservedAlertEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedAlertEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedAlertEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedAlert entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
